import type { StatusCallbacks, TurnContentBlock } from '../core/types.js';
import type { ServerMessage, LogEntry, AgentWindowState } from './types.js';
import { RunRegistry } from './run-registry.js';

export function createStatusBridge(
  runId: string,
  registry: RunRegistry,
  broadcast: (msg: ServerMessage) => void,
): StatusCallbacks {
  const now = (): string => new Date().toISOString();

  return {
    // ── Workflow-level no-ops ──────────────────────────────────────────
    onWorkflowStart: () => {},
    onWorkflowComplete: () => {},
    onWorkflowFailed: () => {},
    onTaskStart: () => {},
    onTaskComplete: () => {},
    onTaskRejected: () => {},
    onTurnStart: () => {},

    // ── Phase ──────────────────────────────────────────────────────────
    onPhaseStart(info) {
      registry.setPhase(runId, info.phase);
      broadcast({
        type: 'workflow_phase',
        workflowId: runId,
        phase: info.phase,
        completed: [...registry.getRun(runId)!.completedPhases],
      });
    },

    onPhaseComplete(info) {
      broadcast({
        type: 'workflow_phase',
        workflowId: runId,
        phase: info.phase,
        completed: [...registry.getRun(runId)!.completedPhases],
      });
    },

    // ── Agent lifecycle ────────────────────────────────────────────────
    onAgentSpawn(info) {
      const agent: AgentWindowState = {
        agentId: info.agentId,
        profile: info.profile,
        taskId: info.taskId,
        active: true,
        log: [],
      };
      registry.addAgent(runId, agent);
      broadcast({ type: 'agent_spawned', workflowId: runId, agent });
    },

    onAgentComplete(info) {
      registry.completeAgent(runId, info.agentId);
      broadcast({ type: 'agent_complete', workflowId: runId, agentId: info.agentId });
    },

    // ── Turn end – content blocks ──────────────────────────────────────
    onTurnEnd(info) {
      if (!info.contentBlocks) return;
      for (const block of info.contentBlocks) {
        const entry = contentBlockToLogEntry(block);
        registry.addAgentLogEntry(runId, info.agentId, entry);
        broadcast({ type: 'agent_log', workflowId: runId, agentId: info.agentId, entry });
      }
    },

    // ── Tool calls ─────────────────────────────────────────────────────
    onToolCallStart(info) {
      const entry: LogEntry = {
        id: info.toolCallId,
        timestamp: now(),
        type: 'tool_call_start',
        content: info.toolName,
      };
      registry.addAgentLogEntry(runId, info.agentId, entry);
      broadcast({ type: 'agent_log', workflowId: runId, agentId: info.agentId, entry });
    },

    onToolCallEnd(info) {
      const entry: LogEntry = {
        id: info.toolCallId + '-end',
        timestamp: now(),
        type: 'tool_call_end',
        content: info.toolName,
        metadata: { isError: info.isError },
      };
      registry.addAgentLogEntry(runId, info.agentId, entry);
      broadcast({ type: 'agent_log', workflowId: runId, agentId: info.agentId, entry });
    },

    // ── Error / Decision ───────────────────────────────────────────────
    onError(info) {
      const entry: LogEntry = {
        id: crypto.randomUUID(),
        timestamp: now(),
        type: 'error',
        content: info.error,
        metadata: { phase: info.phase },
      };
      registry.addAgentLogEntry(runId, info.agentId, entry);
      broadcast({ type: 'agent_log', workflowId: runId, agentId: info.agentId, entry });
    },

    onDecision(info) {
      const entry: LogEntry = {
        id: crypto.randomUUID(),
        timestamp: now(),
        type: 'decision',
        content: info.decision,
        metadata: { reasoning: info.reasoning },
      };
      registry.addAgentLogEntry(runId, info.agentId, entry);
      broadcast({ type: 'agent_log', workflowId: runId, agentId: info.agentId, entry });
    },

    // ── Sidebar ────────────────────────────────────────────────────────
    onSidebarUpdate(info) {
      registry.updateSidebar(runId, info);
      broadcast({
        type: 'workflow_sidebar',
        workflowId: runId,
        sidebar: registry.getRun(runId)!.sidebar,
      });
    },
  };
}

// ─── Helpers ────────────────────────────────────────────────────────────────

function contentBlockToLogEntry(block: TurnContentBlock): LogEntry {
  const id = crypto.randomUUID();
  const timestamp = new Date().toISOString();

  switch (block.type) {
    case 'text':
      return { id, timestamp, type: 'text', content: block.text };
    case 'thinking':
      return {
        id,
        timestamp,
        type: 'thinking',
        content: block.redacted ? '[redacted]' : block.thinking,
      };
    case 'toolCall':
      return {
        id,
        timestamp,
        type: 'tool_call',
        content: block.name,
        metadata: { arguments: block.arguments },
      };
  }
}

// ─── Re-exports from @earendil-works/pi-coding-agent ───────────────────────
export { AgentSession, AuthStorage, DefaultResourceLoader, SessionManager } from '@earendil-works/pi-coding-agent';
export type { ThinkingLevel };

// ─── Peer dependency re-exports (not re-exported by pi-coding-agent) ───────
import type { ThinkingLevel } from '@earendil-works/pi-agent-core';

export { getModel, parseJsonWithRepair } from '@earendil-works/pi-ai';
export type { Model } from '@earendil-works/pi-ai';

// ─── Agent Profile ──────────────────────────────────────────────────────────
export interface AgentProfile {
  id: string;
  name: string;
  provider: string;
  model: string;
  thinkingLevel: ThinkingLevel;
  systemPrompt: string;
  excludeTools: string[];
  includeTools: string[];
}

// ─── Task Tracking ──────────────────────────────────────────────────────────
export type TaskStatus = 'blocked' | 'ready' | 'claimed' | 'implementing' | 'reviewing' | 'done';

export interface Task {
  id: string;
  title: string;
  prompt: string;
  profile: string;
  files: string[];
  dependencies: string[];
  status: TaskStatus;
  assignedAgent?: string;
  result?: unknown;
  reviewFeedback?: string;
  isCode?: boolean;
}

// ─── Workflow Phases ────────────────────────────────────────────────────────
export type WorkflowPhase =
  | 'scouting'
  | 'scouting_review'
  | 'planning'
  | 'plan_review'
  | 'implementing'
  | 'final_review'
  | 'done';

export interface WorkflowState {
  taskPrompt: string;
  currentPhase: WorkflowPhase;
  completedPhases: WorkflowPhase[];
  tasks: Task[];
  /** Scouting reports stored as opaque values; consumers should cast to their specific schema type */
  scoutingReports: unknown[];
  /** Plan stored as opaque value; consumers should cast to their specific schema type */
  plan: unknown;
  research?: string;
  /** Plan review feedback text from the reviewer when a plan is rejected */
  planReviewFeedback?: string;
  /** Specific improvement suggestions from the plan reviewer */
  planReviewSuggestions?: string[];
  stats: {
    totalTokens: number;
    totalCost: number;
    agentCount: number;
  };
}

// ─── Audit Events ───────────────────────────────────────────────────────────
export type AuditEvent =
  | { type: 'agent_start'; agentId: string; profile: AgentProfile; taskId?: string; timestamp: string }
  | { type: 'agent_end'; agentId: string; result: unknown; taskId?: string; timestamp: string }
  | { type: 'decision'; agentId: string; decision: string; reasoning: string; taskId?: string; timestamp: string }
  | { type: 'structured_output'; agentId: string; output: unknown; taskId?: string; timestamp: string }
  | { type: 'error'; agentId: string; error: string; taskId?: string; timestamp: string };

// ─── Structured Output ──────────────────────────────────────────────────────
export interface StructuredOutputOptions {
  maxRetries: number;
  retryPrompt?: string;
}

// ─── Status Callbacks ──────────────────────────────────────────────────────
export interface WorkflowStatusCallbacks {
  onWorkflowStart?: (info: { taskPrompt: string; resumed: boolean; workDir: string }) => void;
  onPhaseStart?: (info: { phase: string; round: number }) => void;
  onPhaseComplete?: (info: { phase: string; durationMs: number }) => void;
  onAgentSpawn?: (info: { agentId: string; profile: string; phase: string; taskId?: string }) => void;
  onAgentComplete?: (info: { agentId: string; profile: string; phase: string; taskId?: string }) => void;
  onTaskStart?: (info: { taskId: string; title: string; agentId: string }) => void;
  onTaskComplete?: (info: { taskId: string; title: string }) => void;
  onTaskRejected?: (info: { taskId: string; title: string; reason: string }) => void;
  onDecision?: (info: { agentId: string; decision: string; reasoning: string; taskId?: string }) => void;
  onError?: (info: { agentId: string; error: string; phase: string; taskId?: string }) => void;
  onWorkflowComplete?: (info: { totalDurationMs: number; agentCount: number }) => void;
  onWorkflowFailed?: (info: { error: Error; phase: string }) => void;
  onSidebarUpdate?: (info: { title?: string; indicator?: string; phases?: Array<{ id: string; label: string; icon: string }> }) => void;
}

export type TurnContentBlock =
  | { type: 'text'; text: string }
  | { type: 'thinking'; thinking: string; redacted?: boolean }
  | { type: 'toolCall'; id: string; name: string; arguments: Record<string, unknown> };

export interface AgentStatusCallbacks {
  onTurnStart?: (info: { agentId: string; turn: number }) => void;
  onTurnEnd?: (info: {
    agentId: string;
    turn: number;
    tokens?: { input: number; output: number };
    contentBlocks?: TurnContentBlock[];
  }) => void;
  onToolCallStart?: (info: { agentId: string; toolName: string; toolCallId: string; arguments: Record<string, unknown> }) => void;
  onToolCallEnd?: (info: { agentId: string; toolName: string; toolCallId: string; isError: boolean }) => void;
}

export type StatusCallbacks = WorkflowStatusCallbacks & AgentStatusCallbacks;

// ─── Agent Loop Result ──────────────────────────────────────────────────────
export interface AgentLoopResult<T> {
  result: T;
  attempts: number;
  totalTokens: { input: number; output: number };
}

// ─── Workflow Run Options ──────────────────────────────────────────────────
export interface WorkflowRunOptions {
  cwd: string;
  workDir: string;
  maxConcurrentTasks?: number;
  apiKeys?: Record<string, string>;
  onStatus?: StatusCallbacks;
  /** Abort signal for cooperative cancellation (e.g. SIGINT) */
  signal?: AbortSignal;
}

// ─── Workflow Entry ───────────────────────────────────────────────────────
export interface WorkflowEntry {
  name: string;
  source: 'local' | 'global';
  path: string;
}

// ─── Workflow Module ────────────────────────────────────────────────────────
export interface WorkflowModule {
  run(taskPrompt: string, options: WorkflowRunOptions): Promise<void>;
  name?: string;
  description?: string;
}

// ─── Harness Creation ───────────────────────────────────────────────────────
export interface HarnessCreationOptions {
  profile: AgentProfile;
  cwd: string;
  apiKeys?: Record<string, string>;
  onAgentStatus?: AgentStatusCallbacks;
  sessionDir?: string;
  resumeSessionPath?: string;
}

/**
 * WebSocket protocol types for the engin web interface.
 *
 * These types define the message protocol between the server and connected
 * clients (e.g. the web UI). All messages are JSON-serialisable.
 *
 * Discriminated unions use the `type` field as the discriminant.
 */

// ─── Shared value types ─────────────────────────────────────────────────────

export interface PhaseDescriptor {
  id: string;
  label: string;
  icon: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type:
    | 'text'
    | 'thinking'
    | 'tool_call'
    | 'tool_call_start'
    | 'tool_call_end'
    | 'decision'
    | 'error';
  content: string;
  metadata?: Record<string, unknown>;
}

export interface AgentWindowState {
  agentId: string;
  profile: string;
  taskId?: string;
  active: boolean;
  log: LogEntry[];
}

export interface SidebarInfo {
  title: string;
  indicator: string;
  phases?: PhaseDescriptor[];
}

export interface WorkflowSummary {
  id: string;
  workflowName: string;
  status: 'running' | 'completed' | 'failed';
  sidebar: SidebarInfo;
  startedAt: string;
  completedAt?: string;
}

// ─── Server → Client messages ───────────────────────────────────────────────

export type ServerMessage =
  | { type: 'init'; workflows: WorkflowSummary[] }
  | { type: 'workflow_started'; summary: WorkflowSummary }
  | { type: 'workflow_sidebar'; workflowId: string; sidebar: SidebarInfo }
  | { type: 'workflow_phase'; workflowId: string; phase: string; completed: string[] }
  | { type: 'workflow_complete'; summary: WorkflowSummary }
  | { type: 'workflow_failed'; summary: WorkflowSummary; error: string; phase: string }
  | { type: 'agent_spawned'; workflowId: string; agent: AgentWindowState }
  | { type: 'agent_log'; workflowId: string; agentId: string; entry: LogEntry }
  | { type: 'agent_complete'; workflowId: string; agentId: string };

// ─── Client → Server messages ───────────────────────────────────────────────

export type ClientMessage =
  | { type: 'start_workflow'; workflowName: string; taskPrompt: string; maxConcurrent?: number }
  | { type: 'select_workflow'; workflowId: string }
  | { type: 'cancel_workflow'; workflowId: string };

// ─── Server options ─────────────────────────────────────────────────────────

export interface WebServerOptions {
  host: string;
  port: number;
  cwd: string;
}

import type {
  AgentWindowState,
  LogEntry,
  PhaseDescriptor,
  SidebarInfo,
  WorkflowSummary,
} from './types.js';

// ─── Internal RunEntry ──────────────────────────────────────────────────────

interface RunEntry {
  id: string;
  workflowName: string;
  status: 'running' | 'completed' | 'failed';
  sidebar: SidebarInfo;
  startedAt: string;
  completedAt?: string;
  currentPhase: string;
  completedPhases: string[];
  agents: Map<string, AgentWindowState>;
  abortController: AbortController;
}

// ─── RunRegistry ────────────────────────────────────────────────────────────

/**
 * Tracks active and past workflow runs in memory.
 *
 * All run records are kept in insertion order so that clients can display a
 * stable, chronological list.  The registry exposes a high-level API that the
 * WebSocket server calls as workflow lifecycle events fire.
 */
export class RunRegistry {
  private runs: Map<string, RunEntry> = new Map();
  private order: string[] = [];

  // ─── Lifecycle ─────────────────────────────────────────────────────────

  /**
   * Create a new workflow run and return its unique ID.
   */
  createRun(workflowName: string): string {
    const id = crypto.randomUUID();
    const entry: RunEntry = {
      id,
      workflowName,
      status: 'running',
      sidebar: { title: workflowName, indicator: '...' },
      startedAt: new Date().toISOString(),
      currentPhase: '',
      completedPhases: [],
      agents: new Map(),
      abortController: new AbortController(),
    };
    this.runs.set(id, entry);
    this.order.push(id);
    return id;
  }

  /**
   * Mark a run as completed.  Returns the finished summary.
   * Throws if the run ID does not exist.
   */
  completeRun(runId: string): WorkflowSummary {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    entry.status = 'completed';
    entry.completedAt = new Date().toISOString();
    return this.toSummary(entry);
  }

  /**
   * Mark a run as failed.  Returns the finished summary.
   * Throws if the run ID does not exist.
   */
  failRun(runId: string, _errorMsg: string): WorkflowSummary {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    entry.status = 'failed';
    entry.completedAt = new Date().toISOString();
    return this.toSummary(entry);
  }

  // ─── Sidebar / Phase ───────────────────────────────────────────────────

  /**
   * Merge partial sidebar information into the run's sidebar.
   * Throws if the run ID does not exist.
   */
  updateSidebar(
    runId: string,
    info: { title?: string; indicator?: string; phases?: PhaseDescriptor[] },
  ): void {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    if (info.title !== undefined) {
      entry.sidebar.title = info.title;
    }
    if (info.indicator !== undefined) {
      entry.sidebar.indicator = info.indicator;
    }
    if (info.phases !== undefined) {
      entry.sidebar.phases = info.phases;
    }
  }

  /**
   * Advance the run to a new phase.  If a phase was already active it is
   * first pushed onto the completed list.
   * Throws if the run ID does not exist.
   */
  setPhase(runId: string, phase: string): void {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    if (entry.currentPhase) {
      entry.completedPhases.push(entry.currentPhase);
    }
    entry.currentPhase = phase;
  }

  // ─── Agents ────────────────────────────────────────────────────────────

  /**
   * Register (or replace) an agent window for the given run.
   * Throws if the run ID does not exist.
   */
  addAgent(runId: string, agent: AgentWindowState): void {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    entry.agents.set(agent.agentId, agent);
  }

  /**
   * Mark an agent as inactive (completed) within a run.
   * Throws if either the run ID or the agent ID does not exist.
   */
  completeAgent(runId: string, agentId: string): void {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    const agent = entry.agents.get(agentId);
    if (!agent) {
      throw new Error(`Agent ${agentId} not found in run ${runId}`);
    }
    agent.active = false;
  }

  /**
   * Append a log entry to an agent's log.  If the agent does not yet exist
   * it is auto-created with an empty profile and active=true.
   * Throws only if the run ID does not exist.
   */
  addAgentLogEntry(runId: string, agentId: string, logEntry: LogEntry): void {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    let agent = entry.agents.get(agentId);
    if (!agent) {
      agent = { agentId, profile: '', active: true, log: [logEntry] };
      entry.agents.set(agentId, agent);
    } else {
      agent.log.push(logEntry);
    }
  }

  // ─── Queries ───────────────────────────────────────────────────────────

  /**
   * Return a summary of a single run.
   * Throws if the run ID does not exist.
   */
  getSummary(runId: string): WorkflowSummary {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    return this.toSummary(entry);
  }

  /**
   * Return summaries of all runs in insertion order.
   */
  getAllSummaries(): WorkflowSummary[] {
    return this.order.map((id) => this.toSummary(this.runs.get(id)!));
  }

  /**
   * Return the raw entry (or undefined) for advanced internal use.
   */
  getRun(runId: string): RunEntry | undefined {
    return this.runs.get(runId);
  }

  /**
   * Return the AbortController for a run, or undefined if it doesn't exist.
   */
  getAbortController(runId: string): AbortController | undefined {
    return this.runs.get(runId)?.abortController;
  }

  // ─── Internal helpers ──────────────────────────────────────────────────

  private toSummary(entry: RunEntry): WorkflowSummary {
    return {
      id: entry.id,
      workflowName: entry.workflowName,
      status: entry.status,
      sidebar: entry.sidebar,
      startedAt: entry.startedAt,
      completedAt: entry.completedAt,
    };
  }
}

import { describe, expect, it, mock } from 'bun:test';
import { createStatusBridge } from '../../src/web/status-bridge.ts';
import { RunRegistry } from '../../src/web/run-registry.ts';
import type { StatusCallbacks, TurnContentBlock } from '../../src/core/types.ts';
import type { ServerMessage, AgentWindowState, LogEntry } from '../../src/web/types.ts';

// ─── Helpers ────────────────────────────────────────────────────────────────

function setup() {
  const registry = new RunRegistry();
  const runId = registry.createRun('Test Workflow');
  const broadcast = mock<(msg: ServerMessage) => void>();
  const bridge = createStatusBridge(runId, registry, broadcast);
  return { registry, runId, broadcast, bridge };
}

/**
 * Assert that broadcast was called once with a message matching the given
 * partial shape.
 */
function expectBroadcast(
  broadcast: ReturnType<typeof mock>,
  expected: Partial<ServerMessage>,
) {
  expect(broadcast).toHaveBeenCalledTimes(1);
  const msg = broadcast.mock.calls[0][0];
  expect(msg).toMatchObject(expected as Record<string, unknown>);
}

/**
 * Assert that broadcast was called N times with messages matching the
 * given array of partial shapes, in order.
 */
function expectBroadcastN(
  broadcast: ReturnType<typeof mock>,
  expected: Partial<ServerMessage>[],
) {
  expect(broadcast).toHaveBeenCalledTimes(expected.length);
  for (let i = 0; i < expected.length; i++) {
    expect(broadcast.mock.calls[i][0]).toMatchObject(
      expected[i] as Record<string, unknown>,
    );
  }
}

// ─── No-op callbacks ────────────────────────────────────────────────────────

describe('no-op callbacks', () => {
  const noOps: (keyof StatusCallbacks)[] = [
    'onWorkflowStart',
    'onWorkflowComplete',
    'onWorkflowFailed',
    'onTaskStart',
    'onTaskComplete',
    'onTaskRejected',
    'onTurnStart',
  ];

  for (const name of noOps) {
    it(`${name} does not broadcast or throw`, () => {
      const { bridge, broadcast } = setup();
      const cb = bridge[name] as (...args: never[]) => void;
      expect(() => cb()).not.toThrow();
      expect(broadcast).not.toHaveBeenCalled();
    });
  }
});

// ─── onPhaseStart ───────────────────────────────────────────────────────────

describe('onPhaseStart', () => {
  it('updates the phase via registry and broadcasts workflow_phase', () => {
    const { registry, runId, broadcast, bridge } = setup();
    bridge.onPhaseStart?.({ phase: 'scouting', round: 1 });

    // Registry updated
    const entry = registry.getRun(runId)!;
    expect(entry.currentPhase).toBe('scouting');
    expect(entry.completedPhases).toEqual([]);

    // Broadcast
    expectBroadcast(broadcast, {
      type: 'workflow_phase',
      workflowId: runId,
      phase: 'scouting',
      completed: [],
    });
  });

  it('moves previous phase to completedPhases when called twice', () => {
    const { registry, runId, broadcast, bridge } = setup();
    bridge.onPhaseStart?.({ phase: 'planning', round: 1 });
    bridge.onPhaseStart?.({ phase: 'implementing', round: 2 });

    const entry = registry.getRun(runId)!;
    expect(entry.currentPhase).toBe('implementing');
    expect(entry.completedPhases).toEqual(['planning']);

    expectBroadcastN(broadcast, [
      { type: 'workflow_phase', phase: 'planning', completed: [] },
      { type: 'workflow_phase', phase: 'implementing', completed: ['planning'] },
    ]);
  });

  it('broadcast message includes current completedPhases', () => {
    const { registry, runId, broadcast, bridge } = setup();
    // Manually set a completed phase to verify it appears in broadcast
    registry.setPhase(runId, 'scouting');
    broadcast.mockClear();

    bridge.onPhaseStart?.({ phase: 'planning', round: 1 });
    expectBroadcast(broadcast, {
      type: 'workflow_phase',
      phase: 'planning',
      completed: ['scouting'],
    });
  });
});

// ─── onPhaseComplete ────────────────────────────────────────────────────────

describe('onPhaseComplete', () => {
  it('broadcasts workflow_phase without modifying registry', () => {
    const { registry, runId, broadcast, bridge } = setup();
    // Set a phase first so completedPhases is populated
    registry.setPhase(runId, 'scouting');
    broadcast.mockClear();

    bridge.onPhaseComplete?.({ phase: 'scouting', durationMs: 500 });

    // Registry unchanged
    const entry = registry.getRun(runId)!;
    expect(entry.currentPhase).toBe('scouting'); // unchanged by onPhaseComplete

    // Broadcast
    expectBroadcast(broadcast, {
      type: 'workflow_phase',
      workflowId: runId,
      phase: 'scouting',
      completed: [], // setPhase only moves phase on subsequent calls; here currentPhase is 'scouting' but completedPhases is empty because setPhase was called only once
    });
  });

  it('broadcast reflects current completedPhases from registry', () => {
    const { registry, runId, broadcast, bridge } = setup();
    registry.setPhase(runId, 'scouting');
    registry.setPhase(runId, 'planning'); // now completedPhases = ['scouting']
    broadcast.mockClear();

    bridge.onPhaseComplete?.({ phase: 'planning', durationMs: 300 });
    expectBroadcast(broadcast, {
      type: 'workflow_phase',
      phase: 'planning',
      completed: ['scouting'],
    });
  });
});

// ─── onAgentSpawn ───────────────────────────────────────────────────────────

describe('onAgentSpawn', () => {
  it('adds agent to registry and broadcasts agent_spawned', () => {
    const { registry, runId, broadcast, bridge } = setup();
    bridge.onAgentSpawn?.({
